CombatEntry entry(const CombatContent& c,const SessionEntry& base,int map,TilePosition tile){auto e=c.entries.at("post-pickup");e.map=map;e.playerTile=tile;e.direction=Direction::Up;e.session=base;e.session.flags[1]=true;e.session.flags[18]=true;e.session.flags[10]=false;e.session.flags[13]=false;e.session.conditions={};e.positions.clear();e.directions.clear();e.pages.clear();e.through.clear();return e;}
void settle(CombatScene& scene){for(int n=0;n<3000;++n){if(scene.foreground()==ForegroundKind::None&&!scene.dialogue().active()){return;}scene.update(n%8==0?key():InputFrame{});scene.takePresentation();}throw std::runtime_error("G3-03 fixture flow stalled");}
void choose(CombatScene& scene,int row,bool cancel=false){for(int n=0;n<3000&&!scene.inputPromptView().cursor;++n){scene.update(n%8==0?key():InputFrame{});scene.takePresentation();}need(scene.inputPromptView().cursor.has_value(),"G3-03 choice missing");if(cancel){scene.update(key(InputAction::Cancel));need(scene.inputPromptView().cursor.has_value(),"Cancel0 closed original choice");}for(int n=0;n<row;++n){scene.update(key(InputAction::Down));scene.update({});}scene.update(key());settle(scene);}
EnemyView enemy(const CombatScene& s,const std::string& id){for(const auto& e:s.enemyStates()){if(e.id==id){return e;}}throw std::runtime_error("Missing G3-03 enemy");}
AttackResolution hit(CombatScene& scene,const std::string& id,int receiver){const auto p=findCharacter(scene.world(),id).motion.position();std::set<std::string> ids;return scene.resolveAttack({{(p.x+.5)*16,(p.y+.5)*16},{0,0},AttackKind::Handgun,receiver,0,false},ids);}
