 {auto varied=c;varied.catalog["flows"]["m177-e3-p1"]["steps"]=Json::array({{{"kind","cue"},{"cue","m177-e3-p1-c13"}},{{"kind","domain_value"},{"field","lift_floor"},{"operation","set"},{"value",2}}});auto e=entry(varied,base,177,{11,5});GameSession s(varied.items,e.session,varied.facts);CombatScene scene(varied,s,e,safe);scene.update(key());need(s.variable(626)==0,"Lift committed before shake");for(int n=0;n<17;++n){scene.update({});need(s.variable(626)==0,"Lift shake shorter than18");}scene.update({});need(s.variable(626)==2,"Lift shake never completed");}
