 {auto e=entry(c,base,198,{9,15});for(int n=518;n<=525;++n){e.session.flags[n]=true;}GameSession s(c.items,e.session,c.facts);CombatScene scene(c,s,e,safe);InputFrame down;down.movement=Direction::Down;scene.update(down);scene.update(key());settle(scene);need(scene.mapId()==178,"Shelf natural exit absent");for(int n=518;n<=525;++n){need(!s.flag(n),"Shelf successful exit retained temporary flag");}}
