 {auto e=entry(c,base,183,{4,10});GameSession s(c.items,e.session,c.facts);CombatScene scene(c,s,e,safe);const int before=s.count(33);scene.update(key());settle(scene);need(s.flag(544)&&s.count(33)==std::min(99,before+14),"S544 shotgun14 missing");scene.update(key());settle(scene);need(s.count(33)==std::min(99,before+14),"S544 repeated shotgun14");}
