 for(int example=0;example<3;++example){auto bad=c;auto& r=bad.enemies.at("m180-e9").rules;if(example==0){r["attack_sources"].erase(std::to_string(r["runtime_profile"]["grab_back_page"].get<int>()));}if(example==1){r["attack_sources"].begin().value()["actor"]=0;}if(example==2){r["runtime_profile"]["contact_grab_page"]=8;}bool rejected=false;try{validateSceneContent(bad,*bad.maps.begin()->second.sprites);}catch(const std::exception&){rejected=true;}need(rejected,"Missing/unknown action input/contact route accepted");}
