void persistence(const CombatContent& c,const SaveSnapshot& saved,const std::string& source){
 auto native=saved;native.session.worldValues[c.facts.variables.at(626)]=2;native.session.worldFlags[c.facts.switches.at(565)]=true;for(int n=388;n<=395;++n){native.session.worldFlags[c.facts.switches.at(n)]=true;}native.session.inventory[33]=75;auto bytes=encodeSave(c,native);auto roundtrip=decodeSave(c,bytes);auto restored=prepareRestore(c,roundtrip);need(restored.session->variable(626)==2&&restored.session->flag(565)&&restored.session->count(33)==75,"Native03 capture/validate/restore lost stable facts");for(int n=388;n<=395;++n){need(restored.session->flag(n),"Native03 restore lost zombie fact");}
 for(int example=0;example<4;++example){auto bad=Json::parse(example<2?bytes:source);if(example==0){auto& values=bad["session"]["world_values"];for(auto i=values.begin();i!=values.end();++i){if(i->at(0)==c.facts.variables.at(626)){values.erase(i);break;}}}if(example==1){bad["content"]="post-f5-g3-normal-999";}if(example==2){bad["content"]="post-f5-g3-normal-3";}if(example==3){auto& flags=bad["session"]["world_flags"];for(auto i=flags.begin();i!=flags.end();++i){if(i->at(0)==c.facts.switches.at(450)){flags.erase(i);break;}}}bool rejected=false;try{decodeSave(c,bad.dump());}catch(const std::exception&){rejected=true;}need(rejected,"Native/old source malformed save gained defaults");}
 std::cout<<"G3-03 nonzero626/565/deaths/inventory encode/decode/restore and strict native/02 source rejection passed\n";
}
void focused(const CombatContent& c,const SaveSnapshot& saved,const std::string& source){const auto& base=saved.session;lift(c,base);shelves(c,base);hidden(c,base);actions(c,base);persistence(c,saved,source);}
