  choice=action==0?1:2;const auto& rule=c.enemies.at(id).rules;const auto& profile=rule.at("runtime_profile");const int page=profile.at(action==0?"bite_page":action==1?"grab_front_page":"grab_back_page");const int attack=rule.at("attack_sources").at(std::to_string(page)).at("attack");bool witnessed=false;std::optional<TilePosition> backAnchor;
